always @(rcnt) begin
    case (rcnt)
        4'd0:    rcon_byte = 8'h01;
        4'd1:    rcon_byte = 8'h02;
        4'd2:    rcon_byte = 8'h04;
        4'd3:    rcon_byte = 8'h08;
