always @(posedge clk) begin
    if (rst) begin
        rcnt      <= 4'd0;
        w0        <= 32'd0;
        w1        <= 32'd0;
        w2        <= 32'd0;
        w3        <= 32'd0;
        round_key <= 128'd0;
    end else if (kld) begin
        rcnt <= 4'd0;
        w0   <= initial_key[127:96];
        w1   <= initial_key[95:64];
        w2   <= initial_key[63:32];
        w3   <= initial_key[31:0];
    end else if (rcnt < 4'd10) begin
        rcnt      <= rcnt + 4'd1;
        w0        <= next_w0;
        w1        <= next_w1;
        w2        <= next_w2;
        w3        <= next_w3;
        round_key <= {w0, w1, w2, w3};
    end
end
// STAGE5_SUBTASK_END B5_seq_update

